    expect pow_u32(2_u32, 8_u32) == 256_u32
}

test "pow_u32: 10^3 = 1000" {
    expect pow_u32(10_u32, 3_u32) == 1000_u32
}

test "pow_u32: 3^4 = 81" {
    expect pow_u32(3_u32, 4_u32) == 81_u32
}

test "pow_u32: 16^2 = 256" {
    expect pow_u32(16_u32, 2_u32) == 256_u32
}

test "pow_u32: 1^anything = 1" {
